"use client"

import { useMemo, type ReactNode } from "react"
import { useTheme } from "next-themes"
import { Streamdown } from "streamdown"
import { code } from "@streamdown/code"
import { mermaid } from "@streamdown/mermaid"
import { createMathPlugin } from "@streamdown/math"
import "katex/dist/katex.min.css"
import "./message-markdown.css"

import { cn } from "@/lib/utils"

const math = createMathPlugin({
  singleDollarTextMath: true,
})

const plugins = { code, mermaid, math }

export type MarkdownPatternHandler = {
  pattern: RegExp
  render: (match: RegExpExecArray) => ReactNode
}

export function MessageMarkdown({
  children,
  className,
  isAnimating = false,
  patternHandlers = [],
}: {
  children: string
  className?: string
  isAnimating?: boolean
  patternHandlers?: MarkdownPatternHandler[]
}) {
  const { resolvedTheme } = useTheme()
  const mermaidTheme = resolvedTheme === "dark" ? "dark" : "neutral"

  const components = useMemo(() => {
    if (patternHandlers.length === 0) return undefined
    const process = (text: string): ReactNode => {
      const segments: ReactNode[] = []
      let cursor = 0
      while (cursor < text.length) {
        let earliest: {
          handler: MarkdownPatternHandler
          match: RegExpExecArray
          index: number
        } | null = null
        for (const handler of patternHandlers) {
          handler.pattern.lastIndex = cursor
          const match = handler.pattern.exec(text)
          if (match && (!earliest || match.index < earliest.index)) {
            earliest = { handler, match, index: match.index }
          }
        }
        if (!earliest) {
          segments.push(text.slice(cursor))
          break
        }
        if (earliest.index > cursor) {
          segments.push(text.slice(cursor, earliest.index))
        }
        let rendered: ReactNode
        try {
          rendered = earliest.handler.render(earliest.match) ?? earliest.match[0]
        } catch {
          rendered = earliest.match[0]
        }
        segments.push(rendered)
        cursor = earliest.index + earliest.match[0].length
      }
      return segments
    }
    const wrap = (node: ReactNode): ReactNode => {
      if (Array.isArray(node)) {
        return node.map((child, index) => (
          <span key={index}>{typeof child === "string" ? process(child) : child}</span>
        ))
      }
      return typeof node === "string" ? process(node) : node
    }
    return {
      p: ({ children: kids, ...props }: { children?: ReactNode }) => (
        <p {...props}>{wrap(kids)}</p>
      ),
      li: ({ children: kids, ...props }: { children?: ReactNode }) => (
        <li {...props}>{wrap(kids)}</li>
      ),
    }
  }, [patternHandlers])

  return (
    <Streamdown
      className={cn("lc-markdown max-w-none", className)}
      plugins={plugins}
      shikiTheme={["github-light", "github-dark"]}
      mermaid={{ config: { theme: mermaidTheme } }}
      isAnimating={isAnimating}
      parseIncompleteMarkdown
      codeBlockMaxHeight={Infinity}
      tableMaxHeight={Infinity}
      components={components}
    >
      {children}
    </Streamdown>
  )
}

.lc-markdown {
  color: var(--foreground);
  font-size: 15px;
  line-height: 1.65;
}

.lc-markdown img,
.lc-markdown [data-streamdown="image"] img,
.lc-markdown [data-streamdown="image"] {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius);
}

.lc-markdown .katex {
  color: inherit;
  font-size: 1.05em;
}

.lc-markdown .katex-display {
  margin: 12px 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 4px 0;
}

.lc-markdown table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.lc-markdown th,
.lc-markdown td {
  border: 1px solid var(--border);
  padding: 8px 10px;
  text-align: left;
}

.lc-markdown th {
  background: var(--muted);
  font-weight: 600;
}

.lc-markdown [data-streamdown="mermaid"] {
  overflow-x: auto;
  margin: 10px 0 14px;
}

.lc-markdown p {
  margin: 0 0 12px;
}

.lc-markdown p:last-child {
  margin-bottom: 0;
}

.lc-markdown h1,
.lc-markdown h2,
.lc-markdown h3,
.lc-markdown h4 {
  margin: 18px 0 8px;
  font-weight: 600;
  color: var(--foreground);
  letter-spacing: -0.01em;
}

.lc-markdown h1 {
  font-size: 22px;
}

.lc-markdown h2 {
  font-size: 19px;
}

.lc-markdown h3 {
  font-size: 16.5px;
}

.lc-markdown h4 {
  font-size: 15px;
}

.lc-markdown a {
  color: var(--primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.lc-markdown strong {
  color: var(--foreground);
  font-weight: 600;
}

.lc-markdown ul,
.lc-markdown ol {
  margin: 0 0 12px;
  padding-left: 22px;
}

.lc-markdown li {
  margin: 4px 0;
}

.lc-markdown blockquote {
  margin: 12px 0;
  padding: 4px 0 4px 14px;
  border-left: 3px solid var(--border);
  color: var(--muted-foreground);
}

.lc-markdown hr {
  border: 0;
  border-top: 1px solid var(--border);
  margin: 18px 0;
}

.lc-markdown code:not(pre code) {
  font-family: var(--font-mono);
  font-size: 0.88em;
  background: var(--muted);
  color: var(--foreground);
  padding: 1px 6px;
  border-radius: calc(var(--radius) * 0.6);
}

.lc-markdown [data-streamdown="code-block"] {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  align-items: center;
  margin: 8px 0 12px;
  padding: 0;
  gap: 0;
  overflow: hidden;
  border-radius: var(--radius);
  background: var(--muted);
  content-visibility: visible;
  contain-intrinsic-size: none;
}

.lc-markdown [data-streamdown="code-block-header"] {
  grid-column: 1;
  grid-row: 1;
  height: 2rem;
  min-height: 2rem;
  padding: 0 8px;
  border-bottom: 1px solid var(--border);
}

.lc-markdown [data-streamdown="code-block"] > :has(> [data-streamdown="code-block-actions"]) {
  grid-column: 2;
  grid-row: 1;
  position: static;
  top: auto;
  margin-top: 0;
  height: 2rem;
  padding-right: 6px;
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  border-bottom: 1px solid var(--border);
}

.lc-markdown [data-streamdown="code-block-actions"] {
  height: auto;
  gap: 0;
  padding: 0;
  border: 0;
  background: transparent;
}

.lc-markdown [data-streamdown="code-block-body"] {
  grid-column: 1 / -1;
  grid-row: 2;
  border: 0;
  border-radius: 0;
  padding: 8px 10px;
  background: transparent;
}

.lc-markdown [data-streamdown="code-block"] pre,
.lc-markdown [data-streamdown="code-block"] pre code {
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.lc-markdown pre {
  margin: 8px 0 12px;
  background: var(--muted);
  color: var(--foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.lc-markdown pre code {
  display: block;
  padding: 8px 10px;
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--foreground);
  background: transparent;
  overflow-x: auto;
  line-height: 1.5;
}

